const renderEventPages = async () => {
  const seriesPath = '/en/events/wo-you-ge-peng-you/'
  await Promise.all(guests.map((guest) => mkdir(resolve(out, `events/wo-you-ge-peng-you/${guest.slug}`), { recursive: true })))
  const cards = guests.map((guest) => `<a class="series-card" href="${seriesPath}${guest.slug}/"><img src="/events/wo-you-ge-peng-you/posters/${guest.image}" alt="A Friend of Mine Vol. ${guest.vol} poster" /><div><div class="meta">VOL.${guest.vol} · ${esc(guest.date)}${guest.time ? ` · ${esc(guest.time)}` : ''}</div><h2>${esc(guest.name)}: ${esc(guest.title)}</h2><p>${esc(guest.intro)}</p></div></a>`).join('')
  const shell = (title, content, zhPath, description) => {
    const canonical = title === 'A Friend of Mine' ? seriesPath : `${seriesPath}${guests.find((guest) => `${guest.name}: ${guest.title}` === title)?.slug || ''}/`
    return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="${esc(description)}"><link rel="canonical" href="https://jumpwire.cn${canonical}"><link rel="alternate" hreflang="en" href="https://jumpwire.cn${canonical}"><link rel="alternate" hreflang="zh-CN" href="https://jumpwire.cn${zhPath}"><link rel="stylesheet" href="/seo-page.css"><link rel="stylesheet" href="/about/about.css">${eventStyles}<title>${esc(title)} | JUMPWIRE</title></head><body><nav class="site-nav" aria-label="Main navigation"><a class="site-brand" href="/en/"><img src="/brand-logo-jumpwire.png" alt=""><span>九维精酿<small>JUMPWIRE CRAFT BEER</small></span></a><div class="site-nav-links"><a href="/en/">Home</a><a href="/en/menu/">Menu</a><a href="/en/events/">Events</a><a href="/en/notes/">Notes</a><a href="${zhPath}">中文</a></div></nav><main class="series-page"><a class="back" href="/en/events/">← All events</a>${content}</main><footer class="site-footer"><span>A spark across dimensions · © ${new Date().getFullYear()} 九维精酿 JUMPWIRE</span><nav><a href="/en/menu/">Menu</a><a href="/en/events/">Events</a><a href="/en/about/">About</a></nav></footer><script src="/image-watermark.js" defer></script></body></html>`
  }
  const series = `<header class="series-hero"><p class="eyebrow">JUMPWIRE · EVENT SERIES</p><h1>A Friend of Mine</h1><p>Start with a conversation. Meet an interesting person and discover the world they are living in.</p><p>This JUMPWIRE conversation series invites people from different fields to talk about work, choices, change, interests and the things that may never fit on a résumé.</p></header><section><h2>Past editions</h2><p class="muted">Browse from newest to oldest. Open a card for the guest, topic and event details.</p><div class="series-list">${cards}</div></section><p class="event-note">Dates, guests and registration details are subject to the latest JUMPWIRE announcements. Events take place at No. 5 Fenyangli, Nantian Road, Haizhu District, Guangzhou.</p>`
  await writeFile(resolve(out, 'events/wo-you-ge-peng-you/index.html'), shell('A Friend of Mine', series, '/events/wo-you-ge-peng-you/', 'A Friend of Mine is JUMPWIRE’s conversation series. Meet guests from different fields and explore their stories.'))
  await Promise.all(guests.map((guest) => {
    const path = `${seriesPath}${guest.slug}/`
    const topics = guest.topics.map((topic) => `<li>${esc(topic)}</li>`).join('')
    const content = `<article class="event-detail"><header><p class="eyebrow">JUMPWIRE · VOL.${guest.vol}</p><h1>${esc(guest.title)}</h1><p class="lede">${esc(guest.intro)}</p><div class="event-meta">${esc(guest.date)}${guest.time ? ` · ${esc(guest.time)}` : ''}</div></header><img class="event-poster" src="/events/wo-you-ge-peng-you/posters/${guest.image}" alt="A Friend of Mine Vol. ${guest.vol} poster featuring ${esc(guest.name)}"><h2>Meet the guest</h2><p>${esc(guest.bio)}</p><h2>Topics for this conversation</h2><ul>${topics}</ul><h2>Highlights</h2><p class="event-note">Highlights from the event have not yet been compiled.</p><section><h2>Come by JUMPWIRE</h2><p>The event has ended, but the conversation can continue. Find JUMPWIRE at No. 5 Fenyangli, Nantian Road, Haizhu District, Guangzhou.</p><p><strong>Phone / WeChat:</strong> <a href="tel:+8618529200506">+86 185 2920 0506</a><br><strong>Hours:</strong> Sun–Thu, 8 pm–2 am; Fri–Sat, 8 pm–3 am</p><a class="cta" href="/en/about/#visit">Plan your visit →</a></section><nav class="event-navigation"><a href="${seriesPath}"><span>Series</span><strong>A Friend of Mine</strong></a><a href="/en/events/"><span>More events</span><strong>JUMPWIRE Events</strong></a></nav></article>`
    return writeFile(resolve(out, `events/wo-you-ge-peng-you/${guest.slug}/index.html`), shell(`${guest.name}: ${guest.title}`, content, `/events/wo-you-ge-peng-you/${guest.slug}/`, guest.intro))
  }))
}

const updateSitemap = async () => {
  const sitemapPath = resolve(root, 'public/sitemap.xml')
  const sitemap = await readFile(sitemapPath, 'utf8')
  const routes = ['/en/', '/en/about/', '/en/menu/', '/en/events/', '/en/notes/', ...notes.map((note) => `/en/notes/${note.slug}/`), '/en/events/wo-you-ge-peng-you/', ...guests.map((guest) => `/en/events/wo-you-ge-peng-you/${guest.slug}/`)]
  const missing = routes.filter((route) => !sitemap.includes(`https://jumpwire.cn${route}`)).map((route) => `  <url><loc>https://jumpwire.cn${route}</loc></url>`)
  if (missing.length) await writeFile(sitemapPath, sitemap.replace('</urlset>', `${missing.join('\n')}\n</urlset>`))
}

